import { bootstrapApplication } from '@angular/platform-browser';
import { Component } from '@angular/core';
import { NavbarComponent } from './app/layout/navbar/navbar';
import { SidebarComponent } from './app/layout/sidebar/sidebar';
import { DashboardComponent } from './app/features/dashboard/dashboard';
import { IncomeComponent } from './app/features/income/income';
import { ExpensesComponent } from './app/features/expenses/expenses';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [NavbarComponent, SidebarComponent, DashboardComponent, IncomeComponent, ExpensesComponent],
  template: `
    <div class="app-shell">
      <app-navbar></app-navbar>
      <div class="layout-grid">
        <app-sidebar></app-sidebar>
        <main class="page-content">
          <app-dashboard></app-dashboard>
          <app-income></app-income>
          <app-expenses></app-expenses>
        </main>
      </div>
    </div>
  `,
  styleUrls: ['./styles.scss']
})
export class AppComponent {}

bootstrapApplication(AppComponent);
